# Coins offered for deposits, with empty addresses: add your own wallet
# addresses in the admin (Trading > Deposit wallets) to switch each one on.
WALLETS = [
    ('BTC', 'Bitcoin', 'Bitcoin'),
    ('ETH', 'Ethereum', 'ERC20'),
    ('USDT', 'Tether USD', 'TRC20'),
    ('USDT', 'Tether USD', 'ERC20'),
    ('USDC', 'USD Coin', 'ERC20'),
    ('BNB', 'BNB', 'BEP20'),
    ('SOL', 'Solana', 'Solana'),
    ('XRP', 'XRP', 'XRP Ledger'),
    ('LTC', 'Litecoin', 'Litecoin'),
    ('TRX', 'TRON', 'TRC20'),
]


def add_wallets(apps, schema_editor):
    DepositWallet = apps.get_model('trading', 'DepositWallet')
    for order, (asset, name, network) in enumerate(WALLETS):
        DepositWallet.objects.get_or_create(asset=asset, network=network,
                                            defaults={'name': name, 'sort_order': order})


